// Parse Twilio's application/x-www-form-urlencoded inbound webhook.
const payload = $json && $json.body && typeof $json.body === 'object' ? $json.body : $json;
const stripChannel = value => String(value || '').trim().replace(/^whatsapp:/i, '');
const replyBody = String(payload.Body || '').trim();
const buttonPayload = String(payload.ButtonPayload || '').trim();
const buttonText = String(payload.ButtonText || '').trim();
const replyValue = buttonPayload || buttonText || replyBody;
const fromPhone = stripChannel(payload.From);
if (!/^\+[1-9]\d{7,14}$/.test(fromPhone) || !String(payload.MessageSid || '').trim()) return [];

return [{ json: {
  from_phone: fromPhone,
  to_phone: stripChannel(payload.To),
  reply_body: replyBody,
  reply_value: replyValue,
  reply_keyword: replyValue.toUpperCase(),
  button_payload: buttonPayload,
  button_text: buttonText,
  incoming_wa_id: String(payload.MessageSid).trim(),
  context_wa_id: String(payload.OriginalRepliedMessageSid || '').trim() || null,
  // Present only when Twilio Advanced Opt-Out already handled the keyword. It
  // means the patient has been opted out upstream and has already been sent
  // Twilio's own confirmation.
  opt_out_type: String(payload.OptOutType || '').trim().toUpperCase(),
  received_at: new Date().toISOString()
} }];

// Resolve the Twilio sender to exactly one patient.
const parsed = $('Parse Incoming Message').first().json;
const user = items.map(i => i.json).find(u => String(u.phone || '').trim() === parsed.from_phone);
if (!user) return [];
return [{ json: { ...parsed, user_id: String(user.user_id), user_status: String(user.user_status || '') } }];

// Resolve an inbound reply to one schedule row AND one conversation stage, then
// normalize it. Stage matters: the same word means different things depending on
// which question is open, so correlation happens before mapping, never after.
const parsed = $('Resolve Patient').first().json;
const rows = items.map(i => i.json);
const text = v => String(v == null ? '' : v).trim();
const norm = v => text(v).toUpperCase().replace(/[_-]+/g, ' ').replace(/\s+/g, ' ');

// Stage 1: "Will you do this?" — buttons plus typed accessibility fallbacks.
const COMMITMENT_MAP = {
  'YES': 'YES', 'Y': 'YES', 'YEP': 'YES', 'YEAH': 'YES', 'OK': 'YES', 'OKAY': 'YES',
  'I WILL': 'YES', 'YES I WILL': 'YES', 'COMMIT': 'YES',
  'NO': 'NO', 'N': 'NO', 'NOPE': 'NO', 'CANT': 'NO', "CAN'T": 'NO', 'NOT TODAY': 'NO', 'NO I WONT': 'NO'
};
// Stage 2: "Were you able to complete it?" — here a bare "no" means not yet, and
// a bare "yes" means done. Same tokens, different stage, deliberately.
const OUTCOME_MAP = {
  'DONE': 'DONE', 'COMPLETED': 'DONE', 'YES': 'DONE', 'Y': 'DONE', 'FINISHED': 'DONE',
  'NOT YET': 'NOT_YET', 'NOTYET': 'NOT_YET', 'NO': 'NOT_YET', 'N': 'NOT_YET',
  'NOT STARTED': 'NOT_YET', 'NONE': 'NOT_YET', 'SKIP': 'NOT_YET'
};
// Single-stage nudges keep the original three-way prompt untouched.
const PROGRESS_MAP = {
  'DONE': 'DONE', 'COMPLETED': 'DONE',
  'IN PROGRESS': 'IN_PROGRESS', 'STARTED': 'IN_PROGRESS',
  'NOT YET': 'NOT_YET', 'NOT STARTED': 'NOT_YET', 'NONE': 'NOT_YET', 'SKIP': 'NOT_YET'
};

const value = norm(parsed.reply_value);
const base = {
  ...parsed, canonical_response: null, commitment_response: null, outcome_response: null,
  stage: null, nudge_id: null, schedule_id: null, previous_response: '',
  followup_due_at: '', followup_delay_hours: '', cancel_nudge_ids: [], cancel_rows: [],
  done_count: 0, skip_count: 0, current_streak: 0, consecutive_skips: 0
};

// Webhook retries replay the same MessageSid. Checked first so a retry can never
// re-run a state transition, in either stage.
if (rows.some(r => text(r.response_wa_id) === parsed.incoming_wa_id)) return [{ json: { ...base, reply_type: 'duplicate' } }];

const userRows = rows.filter(r => String(r.user_id) === parsed.user_id);

// STOP is the mandatory ethics opt-out and outranks everything else. It cancels
// every question still open for this patient, so no scheduler pass can deliver a
// follow-up after the patient has asked to stop.
const OPEN_STATUSES = ['awaiting_commitment', 'awaiting_followup'];
if (value === 'STOP' || parsed.opt_out_type === 'STOP') {
  // Each cancelled row carries its stage and its already-recorded answers. An
  // awaiting_followup row has ALREADY answered the commitment (YES); only its
  // outcome window is closing, so overwriting commitment_response there would
  // destroy a real observation — a YES that was cut short by STOP is not the
  // same as a commitment that was never given.
  const cancel = userRows
    .filter(r => OPEN_STATUSES.includes(text(r.status)))
    .map(r => ({
      nudge_id: text(r.nudge_id),
      status: text(r.status),
      prior_commitment: text(r.commitment_response),
      prior_outcome: text(r.outcome_response)
    }))
    .filter(r => r.nudge_id);
  // Twilio Advanced Opt-Out has already replied to the patient; sending our own
  // acknowledgement as well would double-message someone who just asked to stop.
  const replyType = parsed.opt_out_type === 'STOP' ? 'stop_optout' : 'stop';
  return [{ json: { ...base, reply_type: replyType, cancel_rows: cancel, cancel_nudge_ids: cancel.map(r => r.nudge_id) } }];
}

const withRow = (row, stage) => ({
  ...base, stage,
  nudge_id: row.nudge_id,
  schedule_id: row.schedule_id,
  previous_response: text(row.response),
  followup_due_at: text(row.followup_due_at),
  followup_delay_hours: text(row.followup_delay_hours),
  done_count: parseInt(row.done_count) || 0,
  skip_count: parseInt(row.skip_count) || 0,
  current_streak: parseInt(row.current_streak) || 0,
  consecutive_skips: parseInt(row.consecutive_skips) || 0
});

// An explicit WhatsApp reply names the exact message it answers, so context is
// matched most-specific first: the outcome check, then the barrier prompt, then
// the initial nudge.
const ctx = parsed.context_wa_id;
const ctxOutcome = ctx ? userRows.find(r => text(r.followup_wa_id) === ctx) : null;
const ctxBarrier = ctx ? userRows.find(r => text(r.barrier_followup_wa_id) === ctx) : null;
const ctxInitial = ctx ? userRows.find(r => text(r.wa_message_id) === ctx) : null;

// Without context, the patient is answering whichever question was asked most
// recently. asked_at is the moment that specific question went out, not the
// row's last touch, so a stale barrier cannot outrank a fresh outcome check.
const instant = v => { const ms = Date.parse(text(v)); return Number.isFinite(ms) ? ms : 0; };
const open = [];
userRows.forEach(r => {
  const status = text(r.status);
  if (status === 'awaiting_followup' && text(r.followup_sent_at) && !text(r.outcome_response)) {
    open.push({ row: r, stage: 'outcome', asked: instant(r.followup_sent_at) });
  }
  if (status === 'awaiting_commitment' && !text(r.commitment_response)) {
    open.push({ row: r, stage: 'commitment', asked: instant(r.sent_at) });
  }
  if (['sent', 'in_progress', 'not_yet'].includes(status) && text(r.wa_message_id)) {
    open.push({ row: r, stage: 'progress', asked: instant(r.sent_at) || instant(r.last_updated) });
  }
});
open.sort((a, b) => b.asked - a.asked);

// What a reply to the *initial* message means depends on what that message
// asked, not on where the row has since moved. A two-stage nudge asked "Will you
// do this?", so a reply to it is a stage-1 answer even after the row has already
// advanced to awaiting_followup — which is exactly what a second tap on Yes is.
const isTwoStage = r => ['true', 'yes', '1', 'on'].includes(text(r.followup_enabled).toLowerCase()) ||
  text(r.status) === 'awaiting_commitment' || !!text(r.commitment_response);

let target = null;
if (ctxOutcome) target = { row: ctxOutcome, stage: 'outcome' };
else if (ctxBarrier) target = { row: ctxBarrier, stage: 'barrier' };
else if (ctxInitial) target = { row: ctxInitial, stage: isTwoStage(ctxInitial) ? 'commitment' : 'progress' };
else target = open[0] || null;

// A barrier prompt is still outstanding and the reply matches nothing in the
// current stage — that is the barrier answer. Preserved from the single-stage
// flow, and now also reachable after a stage-2 NOT_YET.
const byNewest = (a, b) => instant(b.last_updated) - instant(a.last_updated);
const pendingBarrier = userRows.filter(r => text(r.barrier_followup_wa_id)).sort(byNewest)[0] || null;

if (target && target.stage === 'barrier') return [{ json: { ...withRow(target.row, 'barrier'), reply_type: 'barrier' } }];

if (target && target.stage === 'commitment') {
  const commitment = COMMITMENT_MAP[value] || null;
  // Already answered: refresh idempotency only. Never re-derive followup_due_at,
  // or a second Yes would arm a second follow-up.
  if (text(target.row.commitment_response)) {
    return [{ json: { ...withRow(target.row, 'commitment'), reply_type: 'commitment_repeat', commitment_response: text(target.row.commitment_response) } }];
  }
  if (commitment === 'YES') return [{ json: { ...withRow(target.row, 'commitment'), reply_type: 'commit_yes', commitment_response: 'YES' } }];
  if (commitment === 'NO') return [{ json: { ...withRow(target.row, 'commitment'), reply_type: 'commit_no', commitment_response: 'NO' } }];
}

if (target && target.stage === 'outcome') {
  const outcome = OUTCOME_MAP[value] || null;
  if (outcome === 'DONE') return [{ json: { ...withRow(target.row, 'outcome'), reply_type: 'done', canonical_response: 'DONE', outcome_response: 'DONE' } }];
  if (outcome === 'NOT_YET') return [{ json: { ...withRow(target.row, 'outcome'), reply_type: 'not_yet', canonical_response: 'NOT_YET', outcome_response: 'NOT_YET' } }];
}

if (target && target.stage === 'progress') {
  const progress = PROGRESS_MAP[value] || null;
  if (progress === 'DONE') return [{ json: { ...withRow(target.row, 'progress'), reply_type: 'done', canonical_response: 'DONE' } }];
  if (progress === 'IN_PROGRESS') return [{ json: { ...withRow(target.row, 'progress'), reply_type: 'in_progress', canonical_response: 'IN_PROGRESS' } }];
  if (progress === 'NOT_YET') return [{ json: { ...withRow(target.row, 'progress'), reply_type: 'not_yet', canonical_response: 'NOT_YET' } }];
}

if (pendingBarrier) return [{ json: { ...withRow(pendingBarrier, 'barrier'), reply_type: 'barrier' } }];
return [{ json: { ...base, reply_type: 'unknown' } }];

// Map a barrier reply to the fixed research enum.
const body = String($json.reply_body || $json.reply_value || '').trim().toLowerCase();
const map = {
  '1': 'stress', 'stress': 'stress',
  '2': 'fatigue', 'tired': 'fatigue', 'fatigue': 'fatigue', 'exhausted': 'fatigue',
  '3': 'time', 'no time': 'time', 'busy': 'time', 'time': 'time',
  '4': 'goal_too_hard', 'too hard': 'goal_too_hard', 'hard': 'goal_too_hard', 'difficult': 'goal_too_hard',
  '5': 'life_event', 'life event': 'life_event', 'life': 'life_event',
  '6': 'environment', 'environment': 'environment', 'environ': 'environment',
  '7': 'social', 'social': 'social',
  '8': 'other', 'other': 'other'
};
return [{ json: { ...$json, barrier_tag: map[body] || 'other' } }];

// Build a deterministic free-form acknowledgement inside the user-opened 24-hour window.
const result = $('Classify Reply').first().json;
const sid = String($env.TWILIO_ACCOUNT_SID || '').trim();
const token = String($env.TWILIO_AUTH_TOKEN || '').trim();
const from = String($env.TWILIO_WHATSAPP_FROM || '').trim();
if (!sid || !token || !/^whatsapp:\+[1-9]\d{7,14}$/.test(from)) throw new Error('Missing or invalid Twilio feedback credentials');
const hours = String(result.followup_delay_hours || '').trim();
const messages = {
  commit_yes: 'Great — noted. I will check back' + (hours ? ' in about ' + hours + ' hour(s)' : ' later') + ' to see how it went.',
  commit_no: 'Thanks for letting me know. No check-in for this one.',
  commitment_repeat: 'Thanks — already noted. I will still check back later.',
  done: 'Thanks — your progress has been marked as Done.',
  in_progress: 'Thanks — your progress has been marked as In progress. Tap Done when you complete it.',
  not_yet: 'Thanks — your progress has been marked as Not yet. What got in the way?\n\n1 = Stress\n2 = Tired or fatigued\n3 = Not enough time\n4 = Goal too hard\n5 = Life event\n6 = Environment\n7 = Social\n8 = Other\n\nReply with a number or keyword.',
  barrier: 'Thanks — your response has been recorded.',
  stop: 'You have been opted out. You will not receive any more health-plan messages.',
  unknown: 'Please tap one of the buttons on the latest check-in. You can also type STOP at any time.'
};
// stop_optout is absent on purpose: Twilio Advanced Opt-Out has already confirmed
// to the patient, so returning nothing here prevents a duplicate message.
const body = messages[result.reply_type];
if (!body) return [];
const encodeForm = pairs => pairs.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
return [{ json: { ...result, outbound_body: body, twilio_url: 'https://api.twilio.com/2010-04-01/Accounts/' + sid + '/Messages.json', twilio_authorization: 'Basic ' + Buffer.from(sid + ':' + token).toString('base64'), twilio_form: encodeForm([['From', from], ['To', 'whatsapp:' + result.from_phone], ['Body', body]]) } }];

// Only NOT_YET confirmations become pending barrier prompts.
const result = $('Classify Reply').first().json;
const response = items[0].json || {};
if (result.reply_type !== 'not_yet') return [];
if (!response.sid) throw new Error('Twilio barrier follow-up response missing Message SID');
return [{ json: { nudge_id: result.nudge_id, barrier_followup_wa_id: response.sid } }];

// Fan the opt-out out to one item per still-open question so every pending
// commitment and follow-up is cancelled, not just the one that was replied to.
// Each item carries the stage it was cancelled at, because what counts as
// 'unanswered' differs per stage — see Cancel Pending Follow-ups.
const result = $('Classify Reply').first().json;
const rows = (result.cancel_rows && result.cancel_rows.length)
  ? result.cancel_rows
  : (result.cancel_nudge_ids || []).map(id => ({ nudge_id: id, status: 'awaiting_commitment', prior_commitment: '', prior_outcome: '' }));
return rows.map(r => ({ json: {
  nudge_id: r.nudge_id,
  prior_status: r.status || 'awaiting_commitment',
  prior_commitment: r.prior_commitment || '',
  prior_outcome: r.prior_outcome || ''
} }));
